import { Property } from 'csstype';
import React, {
  Key,
  ReactElement,
  ReactNode,
  forwardRef,
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import { useIntl } from 'react-intl';
import { isElement } from 'react-is';
import styled from 'styled-components';
import useResizeObserver from 'use-resize-observer';

import Borders from '@dynatrace/strato-design-tokens/borders';
import Colors from '@dynatrace/strato-design-tokens/colors';
import Elevations from '@dynatrace/strato-design-tokens/elevations';
import Spacings from '@dynatrace/strato-design-tokens/spacings';
import { ChevronLeftIcon, ChevronRightIcon } from '@dynatrace/strato-icons';

import { RenderTab } from './RenderTab.js';
import { Tab } from './Tab.js';
import { TabPanel } from './TabPanel.js';
import { Button } from '../../buttons/button/Button.js';
import { _useControllableState } from '../../core/hooks/useControllableState.js';
import { _useId } from '../../core/hooks/useId.js';
import { useMergeRefs } from '../../core/hooks/useMergeRefs.js';
import { useRovingFocus } from '../../core/hooks/useRovingFocus.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { ItemElement } from '../../core/types/item.js';
import type { StylingProps } from '../../core/types/styling-props.js';

// #region Types
export interface TabsBaseProps extends StylingProps, DataTestId {
  /**
   * Whether the whole tab group is disabled.
   * @defaultValue false
   */
  disabled?: boolean;
  /** The element's unique identifier. See [MDN](https://developer.mozilla.org/en-US/docs/Web/HTML/Global_attributes/id). */
  id?: string;
  /** The collection of tabs to display. */
  children: ReactNode;
  /** The overflow behavior of the tab panel. */
  panelOverflow?: 'hidden' | 'scroll-y';
}

export type TabsProps = TabsBaseProps &
  (TabsControlledProps | TabsUncontrolledProps);

export interface TabsUncontrolledProps {
  /** The index of the selected tab. */
  selectedIndex?: never;
  /** The default index of the selected tab. */
  defaultIndex?: number;
  /** Handler that is called when the selected tab changes. */
  onChange?: never;
}

export interface TabsControlledProps {
  /** The index of the selected tab. */
  selectedIndex: number;
  /** Handler that is called when the selected tab changes. */
  onChange: (selectedIndex: number) => void;
  /** The default index of the selected tab. */
  defaultIndex?: never;
}
// #endregion

// #region StyledComponents
// FIXME: Fix styled components usage to object notation
const StyledTabs = /* @__PURE__ */ styled.div({
  display: 'flex',
  flexDirection: 'column',
  maxWidth: '100%',
});

// FIXME: Fix styled components usage to object notation
const StyledTabsWrapper = styled.div<{
  $isOverflowingLeft: boolean;
  $isOverflowingRight: boolean;
}>(({ $isOverflowingLeft, $isOverflowingRight }) => {
  const maskCss = `linear-gradient(to right
    ${
      $isOverflowingLeft
        ? `, transparent ${Spacings.Size32}, #fff ${Spacings.Size56}`
        : ''
    }
    ${
      $isOverflowingRight
        ? `,#fff calc(100% - ${Spacings.Size56}), transparent calc(100% - ${Spacings.Size32})`
        : ''
    }
  );`;

  return {
    display: 'flex',
    alignItems: 'center',
    gap: Spacings.Size4,
    maxWidth: '100%',
    overflow: 'auto visible',
    position: 'relative',
    paddingBottom: Spacings.Size4,

    scrollbarWidth: 'none',
    scrollBehavior: 'smooth',

    /*
     * if the tabs are overflowing, a css mask is used to fade-out the background behind the arrows
     * the linear gradient differs depending on where the overflow is happening
     */
    ...(($isOverflowingLeft || $isOverflowingRight) && {
      '-webkit-mask': maskCss,
      mask: maskCss,
      '-webkit-mask-repeat': 'no-repeat',
    }),

    '&::-webkit-scrollbar': {
      display: 'none',
    },
  };
});

const StyledArrowWrapper = /* @__PURE__ */ styled.div({
  position: 'relative',

  // border underneath the tabs that is not faded out
  '&::after': {
    content: "''",
    display: 'block',
    position: 'absolute',
    borderTopWidth: Borders.Width.Default,
    borderTopStyle: Borders.Style.Default as Property.BorderTopStyle,
    borderTopColor: Colors.Border.Neutral.Default,
    bottom: 0,
    left: 0,
    right: 0,
  },
});

const StyledArrowButton = styled(Button)<{ $isLeft: boolean }>(
  ({ $isLeft }) => ({
    position: 'absolute',
    top: 0,
    zIndex: Elevations.Overlay,
    ...($isLeft ? { left: 0 } : { right: 0 }),
  }),
);
// #endregion

/**
 * Tabs organize related content by grouping similar information into views or
 * tab panels that are displayed one at a time.
 */
export const Tabs = /* @__PURE__ */ forwardRef<HTMLDivElement, TabsProps>(
  (props, forwardedRef) => {
    const {
      disabled = false,
      selectedIndex,
      defaultIndex,
      onChange,
      children,
      panelOverflow = 'hidden',
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      ...remainingProps
    } = props;

    const intl = useIntl();

    const tabsUniqueId = props.id ?? _useId();
    const tabsListId = _useId({ prefix: 'tabsList' });

    const childrenArray: ReactElement[] = useMemo(() => {
      return (
        React.Children.map(children, (child, i) => {
          if (isElement(child)) {
            switch (child.type) {
              // Override the key of the child Tab
              case Tab:
                return { ...child, key: `${tabsUniqueId}-tab-${i}` };
              default:
                // eslint-disable-next-line no-console
                console.warn(
                  'Only Tab is a valid child of the Tabs component.',
                );
            }
          } else if (child !== null) {
            // do nothing if the child is null (when rendered conditionally for example) and throw a warning otherwise
            // eslint-disable-next-line no-console
            console.warn(
              'The used child is not supported by the Tabs component.',
            );
          }
        }) || []
      );
    }, [children, tabsUniqueId]);

    // Get disabled keys from the children.
    // We handle the disabled keys on our own and not through the react-aria tablist,
    // because we also want to be able to navigate to disabled tabs via keyboard.
    const disabledKeys = useMemo<Key[]>(() => {
      return childrenArray
        .filter((child) => {
          if (isElement(child)) {
            return child.props.disabled;
          }
          return false;
        })
        .map((child) => {
          return child.key as Key;
        });
    }, [childrenArray]);

    // Get all possible keys from the children.
    const allKeys = useMemo<Key[]>(() => {
      return childrenArray
        .filter((child) => isElement(child))
        .map((child) => {
          return child.key as Key;
        });
    }, [childrenArray]);

    const [selectedKey, setSelectedKey] = useState<Key | null>(null);
    // Selected Roving index can be different to the selected key's index as disabled tabs can't be selected but can be focused
    const [selectedRovingIndex, setSelectedRovingIndex] =
      _useControllableState<number>({
        defaultValue: defaultIndex ?? 0,
        value: selectedIndex,
      });
    // Flag to track changes made internally rather than by the user (consider it as a dirty flag)
    const [isSelectionModified, setIsSelectionModified] =
      useState<boolean>(false);

    // keepMountedKeys
    const keepMountedKeys = useMemo<Key[]>(() => {
      return childrenArray
        .filter((child) => isElement(child))
        .filter((child) => child.props.keepMounted === true)
        .filter((child) => child.key !== selectedKey)
        .map((child) => {
          return child.key as Key;
        });
    }, [childrenArray, selectedKey]);

    const isDisabledKey = useCallback(
      (key: Key | null): boolean =>
        disabled || (key !== null && disabledKeys.includes(key)),
      [disabledKeys, disabled],
    );

    useEffect(() => {
      for (const tab of childrenArray) {
        const nestedChildren = Array.from<ItemElement<HTMLElement>>(
          tab.props.children,
        ).some((item: ItemElement<HTMLElement>) => item && item.type === Tab);

        if (nestedChildren) {
          throw new Error('A Tab should not contain another Tab inside it.');
        }
      }
    }, [childrenArray]);

    const ref = useRef<HTMLDivElement>(null);
    const { containerRef, activeElement } = useRovingFocus<HTMLDivElement>({
      direction: 'both',
      focusableChildrenSelector: '[type="button"],[role="tab"]',
      initialIndex: selectedRovingIndex,
    });

    const rootRef = useMergeRefs([ref, containerRef]);

    // Use layout effect to sync up the active element changes with the selected key
    // useEffect would be faster but could lead to out of sync issues between the active element and selected key
    useLayoutEffect(() => {
      if (activeElement && !isSelectionModified) {
        const activeElementKey = activeElement.getAttribute('data-key');
        const newSelectedIndex = childrenArray.findIndex(
          (child) => child.key === activeElementKey,
        );
        if (activeElementKey !== null && newSelectedIndex !== -1) {
          if (
            !isDisabledKey(activeElementKey) &&
            selectedKey !== activeElementKey
          ) {
            onChange?.(newSelectedIndex);
            setSelectedKey(activeElementKey);
          }
          setSelectedRovingIndex(newSelectedIndex);
        }
      }

      // Track if selection was modified other than by the user
      if (isSelectionModified) {
        setIsSelectionModified(false);
      }
    }, [
      activeElement,
      childrenArray,
      isSelectionModified,
      isDisabledKey,
      onChange,
      setSelectedRovingIndex,
      selectedKey,
    ]);

    const checkDefaultIndex = useCallback(
      () =>
        (selectedIndex !== undefined && defaultIndex === undefined) ||
        (selectedIndex === undefined && defaultIndex !== undefined),
      [defaultIndex, selectedIndex],
    );

    const updateSelectedKey = useCallback(
      (index?: number) => {
        // Track that selection was modified other than by the user
        setIsSelectionModified(true);
        // Fallback to current selected roving index if index is undefined
        const selectionIndex = index ?? selectedRovingIndex;

        if (checkDefaultIndex() && !disabled && selectionIndex !== undefined) {
          const newSelectedKey = allKeys[selectionIndex];

          if (
            newSelectedKey &&
            !isDisabledKey(newSelectedKey) &&
            !(selectedKey === newSelectedKey)
          ) {
            setSelectedKey(newSelectedKey);
            const newSelectedIndex = childrenArray.findIndex(
              (child) => child.key === newSelectedKey,
            );
            setSelectedRovingIndex(newSelectedIndex);
          }
        }
      },
      [
        allKeys,
        checkDefaultIndex,
        childrenArray,
        disabled,
        isDisabledKey,
        selectedKey,
        selectedRovingIndex,
        setSelectedRovingIndex,
      ],
    );

    useEffect(() => {
      updateSelectedKey(selectedIndex);
      // Don't add the updateSelectedKey as it would call itself every time its dependencies change
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [selectedIndex, childrenArray]);

    useEffect(() => {
      updateSelectedKey(defaultIndex);
      // This should only run once in the beginning, since it is used for the uncontrolled version to only select a tab initially.
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    // handle overflow and show/hide arrows
    const [isOverflowingLeft, setIsOverflowingLeft] = useState(false);
    const [isOverflowingRight, setIsOverflowingRight] = useState(false);

    const slideTabsLeft = (): void => {
      ref.current?.scrollBy({
        left: -ref.current.offsetWidth / 2,
        behavior: 'smooth',
      });
    };

    const slideTabsRight = (): void => {
      ref.current?.scrollBy({
        left: ref.current.offsetWidth / 2,
        behavior: 'smooth',
      });
    };

    const updateOverflow = useCallback(() => {
      if (ref.current) {
        const tabsWidth = ref.current.offsetWidth;
        const tabsScrollWidth = ref.current.scrollWidth;
        const scrollDiff = tabsScrollWidth - tabsWidth;
        const tabsScrollLeft = Math.ceil(ref.current.scrollLeft);
        setIsOverflowingRight(
          tabsScrollWidth > tabsWidth && tabsScrollLeft < scrollDiff,
        );
        setIsOverflowingLeft(
          tabsScrollWidth > tabsWidth && tabsScrollLeft !== 0,
        );
      }
    }, []);

    const { width: containerWidth, height: containerHeight } =
      useResizeObserver<HTMLDivElement>({
        ref: ref,
      });

    useLayoutEffect(() => {
      updateOverflow();
    }, [containerWidth, containerHeight, updateOverflow]);

    // Callback for clicking the tab to update the selected key
    const handleTabClick = (key: Key | null) => {
      setSelectedKey(key);
    };

    // Get the children relevant to the selected tab
    const getSelectedTabContent = (
      key: Key | null,
      childrenArray: ReactElement[],
    ): ReactElement | null => {
      const tab = childrenArray.find((child) => child.key === key);
      if (tab !== undefined && tab.props.children) {
        return tab.props.children;
      }
      return null;
    };

    // Get a tab panel's id
    const getTabPanelId = (key: Key | null): string | undefined =>
      key !== null ? `${key}-tabPanel` : undefined;

    // Memoize the tab panel for the selected tab to prevent unnecessary re-renders caused by the Tabs component re-rendering
    const MemoizedSelectedTabPanel = useMemo(
      () =>
        [selectedKey, ...keepMountedKeys].map((currentKey) => (
          <TabPanel
            key={currentKey}
            style={{
              display: currentKey !== selectedKey ? 'none' : '',
            }}
            id={getTabPanelId(currentKey)}
            disabled={isDisabledKey(currentKey)}
            panelOverflow={panelOverflow}
            aria-labelledby={currentKey ? `${currentKey}` : undefined}
            children={getSelectedTabContent(currentKey, childrenArray)}
          />
        )),
      [
        childrenArray,
        isDisabledKey,
        panelOverflow,
        selectedKey,
        keepMountedKeys,
      ],
    );

    // Memoize the Tab list to prevent unnecessary re-renders to the Tab list caused by the Tabs component re-rendering
    const MemoizedTabsList = useMemo(() => {
      return (
        childrenArray !== undefined &&
        childrenArray.map((item) => (
          <RenderTab
            key={item.key}
            tabItem={item}
            isSelected={selectedKey === item.key}
            isDisabled={isDisabledKey(item.key)}
            onClick={() => {
              handleTabClick(item.key);
            }}
            ariaControls={getTabPanelId(item.key)}
          />
        ))
      );
    }, [childrenArray, isDisabledKey, selectedKey]);

    return (
      <StyledTabs
        data-testid={dataTestId}
        ref={forwardedRef}
        className={consumerClassName}
        style={consumerStyle}
        {...remainingProps}
      >
        <StyledArrowWrapper>
          {isOverflowingLeft && (
            <StyledArrowButton
              $isLeft={true}
              variant="default"
              onClick={slideTabsLeft}
              aria-label={intl.formatMessage({
                defaultMessage: 'scroll tabs left',
                id: 'Cv2AP7VKybeuopCP',
                description: 'Aria label to scroll the tabs to the left',
              })}
              aria-controls={tabsListId}
            >
              <Button.Prefix>{<ChevronLeftIcon />}</Button.Prefix>
            </StyledArrowButton>
          )}
          <StyledTabsWrapper
            $isOverflowingLeft={isOverflowingLeft}
            $isOverflowingRight={isOverflowingRight}
            role="tablist"
            aria-orientation="horizontal"
            id={tabsListId}
            ref={rootRef}
            tabIndex={-1}
            onScroll={updateOverflow}
          >
            {MemoizedTabsList}
          </StyledTabsWrapper>
          {isOverflowingRight && (
            <StyledArrowButton
              $isLeft={false}
              variant="default"
              onClick={slideTabsRight}
              aria-label={intl.formatMessage({
                defaultMessage: 'scroll tabs right',
                id: '2YBMATuaXx9/4zBP',
                description: 'Aria label to scroll the tabs to the right',
              })}
              aria-controls={tabsListId}
            >
              <Button.Suffix>{<ChevronRightIcon />}</Button.Suffix>
            </StyledArrowButton>
          )}
        </StyledArrowWrapper>
        {MemoizedSelectedTabPanel}
      </StyledTabs>
    );
  },
);
(Tabs as typeof Tabs & { displayName: string }).displayName = 'Tabs';
